import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { AppShell } from "@/components/shell/AppShell";
import { useEventStream } from "@/hooks/use-event-stream";
import OverviewPage from "./pages/OverviewPage";
import ChatPage from "./pages/ChatPage";
import ToolsPage from "./pages/ToolsPage";
import RoutableModelsPage from "./pages/RoutableModelsPage";
import AgentsPage from "./pages/AgentsPage";
import LlmPage from "./pages/LlmPage";
import ServicesPage from "./pages/ServicesPage";
import SecurityPage from "./pages/SecurityPage";
import ConfigPage from "./pages/ConfigPage";
import InspectorPage from "./pages/InspectorPage";
import StatePage from "./pages/StatePage";
import LogsPage from "./pages/LogsPage";
import WorkflowsPage from "./pages/WorkflowsPage";
import OrchestrationPage from "./pages/OrchestrationPage";
import SkillsPage from "./pages/SkillsPage";
import ContainersPage from "./pages/ContainersPage";
import PrivacyNetworkPage from "./pages/PrivacyNetworkPage";
import OpenSwitchPage from "./pages/OpenSwitchPage";
import OpenFlowPage from "./pages/OpenFlowPage";
import KnowledgePage from "./pages/KnowledgePage";
import GrpcDiagnosticsPage from "./pages/GrpcDiagnosticsPage";
import AccountabilityPage from "./pages/AccountabilityPage";
import BtrfsPage from "./pages/BtrfsPage";
import DataStoresPage from "./pages/DataStoresPage";
import EmbeddingPipelinePage from "./pages/EmbeddingPipelinePage";
import NotFound from "./pages/NotFound";

const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: 1, staleTime: 5000, refetchOnWindowFocus: false } },
});

function AppInner() {
  useEventStream();
  return (
    <AppShell>
      <Routes>
        <Route path="/" element={<OverviewPage />} />
        <Route path="/chat" element={<ChatPage />} />
        <Route path="/tools" element={<ToolsPage />} />
        <Route path="/agents" element={<AgentsPage />} />
        <Route path="/models" element={<RoutableModelsPage />} />
        <Route path="/llm" element={<LlmPage />} />
        <Route path="/services" element={<ServicesPage />} />
        <Route path="/security" element={<SecurityPage />} />
        <Route path="/config" element={<ConfigPage />} />
        <Route path="/inspector" element={<InspectorPage />} />
        <Route path="/state" element={<StatePage />} />
        <Route path="/logs" element={<LogsPage />} />
        <Route path="/workflows" element={<WorkflowsPage />} />
        <Route path="/orchestration" element={<OrchestrationPage />} />
        <Route path="/skills" element={<SkillsPage />} />
        <Route path="/containers" element={<ContainersPage />} />
        <Route path="/privacy-network" element={<PrivacyNetworkPage />} />
        <Route path="/ovs" element={<OpenSwitchPage />} />
            <Route path="/openflow" element={<OpenFlowPage />} />
            <Route path="/knowledge" element={<KnowledgePage />} />
            <Route path="/grpc" element={<GrpcDiagnosticsPage />} />
            <Route path="/accountability" element={<AccountabilityPage />} />
            <Route path="/btrfs" element={<BtrfsPage />} />
            <Route path="/data-stores" element={<DataStoresPage />} />
            <Route path="/embedding" element={<EmbeddingPipelinePage />} />
            <Route path="*" element={<NotFound />} />
      </Routes>
    </AppShell>
  );
}

const App = () => (
  <QueryClientProvider client={queryClient}>
    <TooltipProvider>
      <Toaster />
      <Sonner />
      <BrowserRouter>
        <AppInner />
      </BrowserRouter>
    </TooltipProvider>
  </QueryClientProvider>
);

export default App;

import { useState, useRef, useEffect, useCallback } from "react";
import { Callout } from "@/components/shell/Primitives";
import { JsonRenderer } from "@/components/json/JsonRenderer";
import {
  MessageBubble,
  type LocalMessage,
} from "@/components/chat/MessageBubble";
import { SystemPromptEditor } from "@/components/chat/SystemPromptEditor";
import { useEventStore } from "@/stores/event-store";
import { api } from "@/lib/api";
import { cn } from "@/lib/utils";
import { X, Maximize2, Minimize2, MessageSquare, FileText } from "lucide-react";

type ChatTab = "chat" | "system-prompt";
type LlmModelOption = { id: string; name?: string; available?: boolean };
type ProviderOption = {
  id: string;
  label: string;
  description: string;
  available?: boolean;
};

const FALLBACK_PROVIDER = "factory";

function providerList(payload: unknown): string[] {
  const value = payload as {
    providers?: unknown[];
    current?: unknown;
    provider?: unknown;
  } | null;
  return Array.from(
    new Set(
      [
        value?.current,
        value?.provider,
        ...(Array.isArray(value?.providers) ? value.providers : []),
      ]
        .filter(Boolean)
        .map(String),
    ),
  );
}

function modelList(payload: unknown): LlmModelOption[] {
  const value = payload as { models?: unknown[] } | null;
  const models = Array.isArray(value?.models) ? value.models : [];
  return models
    .map((item) => {
      const model = item as {
        id?: unknown;
        name?: unknown;
        available?: unknown;
      };
      const id = model.id ?? model.name;
      if (!id) return null;
      return {
        id: String(id),
        name: String(model.name ?? id),
        available: model.available !== false,
      };
    })
    .filter(Boolean) as LlmModelOption[];
}

function historyMessages(payload: unknown): LocalMessage[] {
  const value = payload as { messages?: unknown[] } | unknown[];
  const messages = Array.isArray(value)
    ? value
    : Array.isArray(value?.messages)
      ? value.messages
      : [];

  return messages.map((item, index) => {
    const msg = item as {
      id?: unknown;
      role?: unknown;
      content?: unknown;
      timestamp?: unknown;
    };
    return {
      id: String(msg.id ?? `history-${index}`),
      role: String(msg.role ?? "assistant") as LocalMessage["role"],
      content: String(msg.content ?? ""),
      timestamp: msg.timestamp
        ? Date.parse(String(msg.timestamp)) || Date.now()
        : Date.now(),
    };
  });
}

function assistantMessage(payload: unknown): LocalMessage {
  const value = payload as {
    id?: unknown;
    role?: unknown;
    content?: unknown;
    message?: unknown;
    error?: unknown;
  };
  const body =
    value?.content ?? value?.message ?? value?.error ?? "(no response)";
  return {
    id: String(value?.id ?? `msg-${Date.now()}-resp`),
    role: String(value?.role ?? "assistant") as LocalMessage["role"],
    content: typeof body === "string" ? body : JSON.stringify(body, null, 2),
    timestamp: Date.now(),
  };
}

function extractProviderOptions(schema: unknown): ProviderOption[] {
  const s = schema as {
    zeroclaw?: {
      chat_form_schema?: {
        properties?: {
          provider?: { enum?: string[]; description?: string };
        };
      };
    };
  } | null;
  const ids = s?.zeroclaw?.chat_form_schema?.properties?.provider?.enum ?? [];
  return ids.map((id) => ({ id, label: id, description: id, available: true }));
}

function extractModelOptions(schema: unknown): LlmModelOption[] {
  const s = schema as {
    zeroclaw?: {
      chat_form_schema?: {
        properties?: {
          model?: { oneOf?: Array<{ const?: string; title?: string }> };
        };
      };
    };
  } | null;
  const oneOf = s?.zeroclaw?.chat_form_schema?.properties?.model?.oneOf ?? [];
  return oneOf
    .filter(
      (o): o is { const: string; title?: string } =>
        typeof o.const === "string",
    )
    .map((o) => ({
      id: o.const,
      name: o.title ?? o.const,
      available: true,
    }));
}

export default function ChatPage() {
  const { connected } = useEventStore();
  const [activeTab, setActiveTab] = useState<ChatTab>("chat");
  const [messages, setMessages] = useState<LocalMessage[]>([
    {
      id: "sys-1",
      role: "system",
      content: "Connected to Operation-DBUS control plane. Ready for commands.",
      timestamp: Date.now(),
    },
  ]);
  const [draft, setDraft] = useState("");
  const [sessionKey] = useState("default");
  const [schema, setSchema] = useState<unknown>(null);
  const [providerOptions, setProviderOptions] = useState<ProviderOption[]>([]);
  const [provider, setProvider] = useState(FALLBACK_PROVIDER);
  const [models, setModels] = useState<LlmModelOption[]>([]);
  const [model, setModel] = useState("");
  const [gatewayError, setGatewayError] = useState("");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarContent, setSidebarContent] = useState<unknown>(null);
  const [focusMode, setFocusMode] = useState(false);
  const [sending, setSending] = useState(false);
  const threadRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = useCallback(() => {
    threadRef.current?.scrollTo({
      top: threadRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages, scrollToBottom]);

  // Fetch schema once on mount — this drives the entire UI
  useEffect(() => {
    let cancelled = false;
    api.zeroclaw
      .schema()
      .then((payload) => {
        if (cancelled) return;
        setSchema(payload);
        const opts = extractProviderOptions(payload);
        setProviderOptions(opts);
        if (opts.length > 0 && provider === FALLBACK_PROVIDER) {
          setProvider(opts[0].id);
        }
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setGatewayError(err instanceof Error ? err.message : String(err));
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // Derive models from schema whenever provider or schema changes
  useEffect(() => {
    if (!schema) return;
    const nextModels = extractModelOptions(schema);
    setModels(nextModels);
    if (nextModels.length > 0) {
      const currentValid = nextModels.find((m) => m.id === model);
      if (!currentValid) setModel(nextModels[0].id);
    } else {
      setModel("");
    }
  }, [schema, provider]);

  useEffect(() => {
    api.chat
      .history(sessionKey)
      .then((payload) => {
        const loaded = historyMessages(payload);
        if (loaded.length > 0) setMessages(loaded);
      })
      .catch(() => {
        // History is best-effort.
      });
  }, [sessionKey]);

  const switchProvider = async (nextProvider: string) => {
    setProvider(nextProvider);
    setModel("");
    setGatewayError("");
    try {
      await api.zeroclaw.setProvider(nextProvider);
    } catch {
      // Keep the UI selection.
    }
  };

  const switchModel = async (nextModel: string) => {
    setModel(nextModel);
    setGatewayError("");
    try {
      await api.zeroclaw.setModel(nextModel);
    } catch {
      // Some providers require provider-qualified model ids.
    }
  };

  const handleSend = async () => {
    if (!draft.trim() || sending) return;
    const userMsg: LocalMessage = {
      id: `msg-${Date.now()}`,
      role: "user",
      content: draft.trim(),
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, userMsg]);
    setDraft("");
    setSending(true);

    try {
      const response = await api.chat.send(
        sessionKey,
        userMsg.content,
        provider || undefined,
        model || undefined,
      );
      setMessages((prev) => [...prev, assistantMessage(response)]);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      setGatewayError(message);
      setMessages((prev) => [
        ...prev,
        {
          id: `msg-${Date.now()}-error`,
          role: "assistant",
          content: `Error: ${message}`,
          timestamp: Date.now(),
        },
      ]);
    } finally {
      setSending(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const openInSidebar = (data: unknown) => {
    setSidebarContent(data);
    setSidebarOpen(true);
  };

  const tabs: { id: ChatTab; label: string; icon: React.ReactNode }[] = [
    {
      id: "chat",
      label: "Chat",
      icon: <MessageSquare className="h-3.5 w-3.5" />,
    },
    {
      id: "system-prompt",
      label: "System Prompt",
      icon: <FileText className="h-3.5 w-3.5" />,
    },
  ];

  return (
    <div className="flex flex-col h-full">
      {/* Header with tabs */}
      {!focusMode && (
        <div className="border-b border-border shrink-0">
          <div className="flex items-end justify-between gap-4 px-4 py-3">
            <div className="flex items-center gap-4">
              <div>
                <h1 className="text-[26px] font-bold tracking-tight leading-tight text-foreground">
                  Antigravity Chat
                </h1>
                <p className="text-sm text-muted-foreground mt-0.5">
                  Antigravity interface · Zeroclaw model route
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <select
                value={provider}
                onChange={(e) => void switchProvider(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-input bg-card text-sm font-mono focus:border-ring outline-none"
              >
                {(providerOptions.length > 0
                  ? providerOptions
                  : [
                      {
                        id: FALLBACK_PROVIDER,
                        label: FALLBACK_PROVIDER,
                        description: "",
                      },
                    ]
                ).map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.label}
                  </option>
                ))}
              </select>
              <select
                value={model}
                onChange={(e) => void switchModel(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-input bg-card text-sm font-mono focus:border-ring outline-none"
              >
                {models.length === 0 && <option value="">model</option>}
                {models.map((item) => (
                  <option
                    key={item.id}
                    value={item.id}
                    disabled={item.available === false}
                  >
                    {item.name ?? item.id}
                  </option>
                ))}
              </select>
              <button
                onClick={() => setFocusMode(!focusMode)}
                className="p-2 rounded-md hover:bg-muted/30 text-muted-foreground hover:text-foreground transition-colors"
                title="Toggle focus mode"
              >
                <Maximize2 className="h-4 w-4" />
              </button>
            </div>
          </div>
          {/* Tab bar */}
          <div className="flex gap-0 px-4">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  "inline-flex items-center gap-1.5 px-4 py-2 text-xs font-medium border-b-2 transition-colors -mb-px",
                  activeTab === tab.id
                    ? "border-primary text-foreground"
                    : "border-transparent text-muted-foreground hover:text-foreground hover:border-muted-foreground/30",
                )}
              >
                {tab.icon}
                {tab.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {focusMode && (
        <button
          onClick={() => setFocusMode(false)}
          className="absolute top-2 right-2 z-10 p-2 rounded-full bg-card border border-border hover:bg-muted/30 text-muted-foreground"
        >
          <X className="h-4 w-4" />
        </button>
      )}

      {/* Tab content */}
      {activeTab === "system-prompt" ? (
        <SystemPromptEditor />
      ) : (
        <div className={cn("flex flex-1 min-h-0", sidebarOpen && "gap-0")}>
          {/* Thread */}
          <div
            className={cn(
              "flex flex-col flex-1 min-w-0",
              sidebarOpen && "flex-[0_0_60%]",
            )}
          >
            <div
              ref={threadRef}
              className="flex-1 overflow-y-auto px-4 py-4 space-y-4"
              role="log"
            >
              {messages.map((msg) => (
                <MessageBubble
                  key={msg.id}
                  message={msg}
                  onInspect={openInSidebar}
                  onAction={(action, payload) => {
                    const actionMsg: LocalMessage = {
                      id: `msg-${Date.now()}-action`,
                      role: "user",
                      content: `[Action: ${action}] ${JSON.stringify(payload)}`,
                      timestamp: Date.now(),
                    };
                    setMessages((prev) => [...prev, actionMsg]);
                  }}
                />
              ))}
              {sending && (
                <div className="flex gap-3">
                  <div className="h-8 w-8 rounded-full bg-primary/20 flex items-center justify-center text-xs font-bold text-primary shrink-0">
                    AI
                  </div>
                  <div className="rounded-lg bg-card border border-border px-4 py-3 animate-[pulse-dot_1.5s_ease-in-out_infinite]">
                    <span className="text-sm text-muted-foreground">
                      Thinking…
                    </span>
                  </div>
                </div>
              )}
            </div>

            {/* Composer */}
            <div className="border-t border-border px-4 py-3 shrink-0 bg-background">
              {!connected && (
                <Callout variant="default" className="mb-3">
                  Event stream offline; REST chat can still send through the
                  gateway.
                </Callout>
              )}
              {gatewayError && (
                <Callout variant="danger" className="mb-3">
                  {gatewayError}
                </Callout>
              )}
              <div className="flex gap-2">
                <div className="flex-1 relative">
                  <textarea
                    value={draft}
                    onChange={(e) => setDraft(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Message Zeroclaw (↩ to send, Shift+↩ for line breaks)"
                    className="w-full px-3 py-2.5 rounded-lg border border-input bg-card text-sm resize-none min-h-[44px] max-h-40 focus:border-ring focus:ring-1 focus:ring-ring outline-none transition-colors font-sans"
                    rows={1}
                  />
                </div>
                <div className="flex flex-col gap-1.5 shrink-0">
                  <button
                    onClick={() =>
                      setMessages([
                        {
                          id: "sys-new",
                          role: "system",
                          content: "New session started.",
                          timestamp: Date.now(),
                        },
                      ])
                    }
                    className="px-3 py-2 rounded-md border border-border bg-[hsl(var(--bg-elevated))] text-xs font-medium hover:bg-muted/30 transition-colors"
                  >
                    New session
                  </button>
                  <button
                    onClick={() => void handleSend()}
                    disabled={sending || !draft.trim()}
                    className="px-3 py-2 rounded-md bg-primary text-primary-foreground text-xs font-medium hover:bg-primary/90 transition-colors disabled:opacity-50 flex items-center gap-1.5"
                  >
                    {sending ? "Queue" : "Send"}
                    <kbd className="text-[10px] bg-primary-foreground/20 px-1 rounded">
                      ↵
                    </kbd>
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Sidebar — tool output inspector */}
          {sidebarOpen && (
            <div className="flex-[0_0_40%] border-l border-border bg-card flex flex-col min-w-0">
              <div className="flex items-center justify-between px-4 py-2 border-b border-border">
                <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  Inspector
                </span>
                <button
                  onClick={() => setSidebarOpen(false)}
                  className="p-1 rounded hover:bg-muted/30 text-muted-foreground"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              </div>
              <div className="flex-1 overflow-auto p-3">
                {sidebarContent !== null ? (
                  <JsonRenderer data={sidebarContent} />
                ) : (
                  <div className="text-sm text-muted-foreground">
                    Click a tool result to inspect.
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

