//! Zeroclaw / Antigravity proxy handlers
//!
//! Proxies chat requests to the antigravity Python SDK bot running on
//! 127.0.0.1:8081, and serves the combined schema (OpenAPI + zeroclaw
//! projection) for schema-driven UI rendering.

use axum::{
    body::Body,
    extract::Extension,
    http::StatusCode,
    response::Response,
    Json,
};
use serde::Deserialize;
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::sync::Arc;
use tracing::{error, info};

use crate::state::AppState;

const ANTIGRAVITY_BASE: &str = "http://127.0.0.1:8081";

/// Schema-driven chat request — shape matches the antigravity bot's
/// `ChatRequest` so we can forward verbatim.
#[derive(Debug, Deserialize)]
pub struct ZeroclawChatRequest {
    pub message: String,
    #[serde(default)]
    pub session_id: Option<String>,
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
}

/// Proxy chat request to the antigravity bot.
/// POST /api/zeroclaw/chat
pub async fn zeroclaw_chat_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(120))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat", ANTIGRAVITY_BASE);

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat to antigravity bot: {} chars",
        req.message.len()
    );

    match client
        .post(&url)
        .header("Content-Type", "application/json")
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity response body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity response",
                    );
                }
            };

            let axum_status = StatusCode::from_u16(status.as_u16())
                .unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "application/json")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build response"))
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Proxy streaming chat request to the antigravity bot SSE endpoint.
/// POST /api/zeroclaw/chat/stream
pub async fn zeroclaw_chat_stream_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(300))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat/stream", ANTIGRAVITY_BASE);

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat stream to antigravity bot: {} chars",
        req.message.len()
    );

    match client
        .post(&url)
        .header("Content-Type", "application/json")
        .header("Accept", "text/event-stream")
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity stream body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity stream",
                    );
                }
            };

            let axum_status = StatusCode::from_u16(status.as_u16())
                .unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "text/event-stream")
                .header("Cache-Control", "no-cache")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build stream response"))
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Helper to build a JSON error response.
fn json_error_response(status: StatusCode, message: &str) -> Response {
    let body = simd_json::to_string(&json!({"error": message})).unwrap_or_default();
    Response::builder()
        .status(status)
        .header("Content-Type", "application/json")
        .body(Body::from(body))
        .unwrap_or_else(|_| {
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::empty())
                .unwrap()
        })
}

/// Serve the combined schema for schema-driven UI rendering.
///
/// Merges the antigravity bot's OpenAPI schema with the zeroclaw plugin
/// projection (providers, model_routes, tools, structured_output) so the
/// frontend can render the entire chat interface from a single schema.
/// GET /api/zeroclaw/schema
pub async fn zeroclaw_schema_handler(
    Extension(state): Extension<Arc<AppState>>,
) -> Response {
    // Fetch antigravity OpenAPI schema
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let openapi = match client
        .get(format!("{}/openapi.json", ANTIGRAVITY_BASE))
        .send()
        .await
    {
        Ok(resp) => match resp.json::<Value>().await {
            Ok(v) => v,
            Err(e) => {
                error!("Failed to parse antigravity OpenAPI: {}", e);
                json!({})
            }
        },
        Err(e) => {
            error!("Failed to fetch antigravity OpenAPI: {}", e);
            json!({})
        }
    };

    // Fetch zeroclaw projection
    let zeroclaw = match crate::projection_client::get_projection(
        &state.projection_cache,
        "zeroclaw",
    )
    .await
    {
        Some(v) => v,
        None => {
            error!("Zeroclaw projection not available");
            return json_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "Zeroclaw projection not available",
            );
        }
    };

    // Build a JSON Schema for the chat form from zeroclaw providers + model_routes
    let providers = zeroclaw
        .get("providers")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|p| p.get("id").and_then(|v| v.as_str()).map(String::from))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let model_routes = zeroclaw
        .get("model_routes")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|r| {
                    let model = r.get("model").and_then(|v| v.as_str())?;
                    let hint = r.get("hint").and_then(|v| v.as_str());
                    let label = hint.map(|h| format!("{} ({h})", model)).unwrap_or_else(|| model.to_string());
                    Some(json!({"const": model, "title": label}))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let chat_schema = json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "title": "Zeroclaw Chat",
        "properties": {
            "provider": {
                "type": "string",
                "enum": providers,
                "description": "LLM provider route"
            },
            "model": {
                "type": "string",
                "oneOf": model_routes,
                "description": "Model to use for this turn"
            },
            "message": {
                "type": "string",
                "description": "Chat message",
                "minLength": 1
            }
        },
        "required": ["message"]
    });

    let schema = json!({
        "openapi": openapi,
        "zeroclaw": {
            "plugin_state": zeroclaw,
            "chat_form_schema": chat_schema,
            "structured_output": zeroclaw.get("structured_output").cloned().unwrap_or(json!({})),
            "tools": zeroclaw.get("tools").cloned().unwrap_or(json!([])),
        }
    });

    let body = simd_json::to_string(&schema).unwrap_or_default();
    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/json")
        .body(Body::from(body))
        .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build schema response"))
}

//! Chat API Handlers

use axum::{
    extract::{Extension, Path},
    response::{
        sse::{Event, Sse},
        Json,
    },
};
use futures::stream::Stream;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::convert::Infallible;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::mpsc;
use tracing::info;

use crate::orchestrator::OrchestratorEvent;
use crate::state::AppState;
use op_llm::provider::{ChatMessage, ProviderType};
use std::str::FromStr;

#[derive(Debug, Deserialize)]
pub struct ChatRequest {
    pub message: String,
    #[serde(default)]
    pub session_id: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub user_id: Option<String>, // For user-specific API credentials
    #[serde(default)]
    pub container_id: Option<String>, // Privacy container for memory scoping
}

#[derive(Debug, Deserialize)]
pub struct CreateSessionRequest {
    #[serde(default)]
    pub title: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct ChatResponse {
    pub success: bool,
    pub message: String,
    // Frontend-compatible aliases (openclaw/ChatPage.tsx expects these)
    pub content: String,
    pub role: String,
    pub id: String,
    pub tool_name: Option<String>,
    pub error: Option<String>,
    pub tools_executed: Vec<String>,
    pub session_id: String,
    pub model: String,
    pub provider: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub container_id: Option<String>,
}

/// POST /api/chat - Main chat endpoint (Blocking)
pub async fn chat_handler(
    Extension(state): Extension<Arc<AppState>>,
    Json(request): Json<ChatRequest>,
) -> Json<ChatResponse> {
    info!(
        "Chat request: {} chars, user: {:?}",
        request.message.len(),
        request.user_id
    );

    let session_id = request
        .session_id
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    // Ensure session exists
    let _ = state
        .conversations
        .create_session(session_id.clone(), None)
        .await;

    // Resolve container_id: session-persisted first, then request, then user store
    let container_id = if let Some(cid) = state.conversations.get_container_id(&session_id).await {
        Some(cid)
    } else if let Some(cid) = request.container_id.clone() {
        // Persist in session for subsequent messages
        let _ = state
            .conversations
            .set_container_id(&session_id, cid.clone())
            .await;
        Some(cid)
    } else if let Some(user_id) = request.user_id.clone() {
        let cid = state
            .user_store
            .get_user(&user_id)
            .await
            .and_then(|u| u.privacy_container_name);
        if let Some(ref c) = cid {
            let _ = state
                .conversations
                .set_container_id(&session_id, c.clone())
                .await;
        }
        cid
    } else {
        None
    };
    let _ = state
        .conversations
        .append_message(&session_id, ChatMessage::user(request.message.clone()))
        .await;

    let fixed_prompt = op_chat::system_prompt::get_fixed_prompt();
    let (custom_prompt, _) = op_chat::system_prompt::load_custom_prompt().await;
    let system_prompt = if custom_prompt.trim().is_empty() {
        fixed_prompt.to_string()
    } else {
        format!("{fixed_prompt}\n\n{custom_prompt}")
    };
    let messages = vec![
        ChatMessage::system(system_prompt),
        ChatMessage::user(request.message.clone()),
    ];

    let requested_provider = request
        .provider
        .as_deref()
        .filter(|value| !value.is_empty());
    let requested_model = request.model.as_deref().filter(|value| !value.is_empty());
    let selected_model = match requested_model {
        Some(model) => model.to_string(),
        None => state.chat_manager.current_model().await,
    };

    if let Err(e) =
        crate::zeroclaw_routes::ensure_model_available(&state.projection_cache, &selected_model)
            .await
    {
        return Json(ChatResponse {
            success: false,
            message: String::new(),
            content: e.to_string(),
            role: "assistant".to_string(),
            id: format!("msg-{}", uuid::Uuid::new_v4()),
            tool_name: None,
            error: Some(e.to_string()),
            tools_executed: vec![],
            session_id,
            model: selected_model,
            provider: requested_provider.unwrap_or("zeroclaw").to_string(),
            container_id,
        });
    }

    let result = match (requested_provider, requested_model) {
        (Some(provider), Some(model)) => match ProviderType::from_str(provider) {
            Ok(provider_type) if state.chat_manager.has_provider(&provider_type) => {
                state
                    .chat_manager
                    .chat_with(&provider_type, model, messages)
                    .await
            }
            Ok(provider_type) => Err(anyhow::anyhow!(
                "Provider {} is not available",
                provider_type
            )),
            Err(_) => Err(anyhow::anyhow!("Unknown provider: {}", provider)),
        },
        (Some(provider), None) => match ProviderType::from_str(provider) {
            Ok(provider_type) if state.chat_manager.has_provider(&provider_type) => {
                state
                    .chat_manager
                    .chat_with(&provider_type, &selected_model, messages)
                    .await
            }
            Ok(provider_type) => Err(anyhow::anyhow!(
                "Provider {} is not available",
                provider_type
            )),
            Err(_) => Err(anyhow::anyhow!("Unknown provider: {}", provider)),
        },
        (None, Some(model)) => {
            match crate::zeroclaw_routes::route_for_model(&state.projection_cache, model).await {
                Some(route) => match ProviderType::from_str(&route.upstream_provider) {
                    Ok(provider_type) if state.chat_manager.has_provider(&provider_type) => {
                        state
                            .chat_manager
                            .chat_with(&provider_type, model, messages)
                            .await
                    }
                    Ok(provider_type) => Err(anyhow::anyhow!(
                        "Provider {} is not available",
                        provider_type
                    )),
                    Err(_) => Err(anyhow::anyhow!(
                        "Route upstream provider is unknown: {}",
                        route.upstream_provider
                    )),
                },
                None => Err(anyhow::anyhow!("Model is not routed by Zeroclaw")),
            }
        }
        _ => state.chat_manager.chat(messages).await,
    };

    match result {
        Ok(result) => {
            let provider = result.provider.clone();
            let model = result.model.clone();
            let response_message = result.message.content.clone();

            let _ = state
                .conversations
                .append_message(
                    &session_id,
                    ChatMessage::assistant(response_message.clone()),
                )
                .await;

            Json(ChatResponse {
                success: true,
                message: response_message.clone(),
                content: response_message.clone(),
                role: "assistant".to_string(),
                id: format!("msg-{}", uuid::Uuid::new_v4()),
                tool_name: None,
                error: None,
                tools_executed: result
                    .tool_calls
                    .unwrap_or_default()
                    .into_iter()
                    .map(|tool| tool.name)
                    .collect(),
                session_id,
                model,
                provider,
                container_id: container_id.clone(),
            })
        }
        Err(e) => {
            let provider = state.chat_manager.current_provider().await.to_string();
            let model = state.chat_manager.current_model().await;
            Json(ChatResponse {
                success: false,
                message: String::new(),
                content: e.to_string(),
                role: "assistant".to_string(),
                id: format!("msg-{}", uuid::Uuid::new_v4()),
                tool_name: None,
                error: Some(e.to_string()),
                tools_executed: vec![],
                session_id,
                model,
                provider,
                container_id,
            })
        }
    }
}

/// POST /api/chat/stream - Streaming chat endpoint (SSE)
pub async fn chat_stream_handler(
    Extension(state): Extension<Arc<AppState>>,
    Json(request): Json<ChatRequest>,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let session_id = request
        .session_id
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    let (tx, mut rx) = mpsc::channel(100);
    let state_clone = state.clone();
    let message = request.message.clone();
    let session_clone = session_id.clone();

    let _ = state
        .conversations
        .create_session(session_id.clone(), None)
        .await;
    let _ = state
        .conversations
        .append_message(&session_id, ChatMessage::user(request.message.clone()))
        .await;

    tokio::spawn(async move {
        let result = state_clone
            .orchestrator
            .process(&session_clone, &message, Some(tx.clone()))
            .await;

        match result {
            Ok(response) => {
                let _ = tx
                    .send(OrchestratorEvent::Finished {
                        success: response.success,
                        message: response.message.clone(),
                        tools_executed: response.tools_executed.clone(),
                    })
                    .await;
            }
            Err(e) => {
                let _ = tx
                    .send(OrchestratorEvent::Error {
                        message: e.to_string(),
                    })
                    .await;
            }
        }
    });

    // Create stream from receiver
    let stream = async_stream::stream! {
        while let Some(event) = rx.recv().await {
            yield Ok(Event::default().data(simd_json::to_string(&event).unwrap_or_default()));
        }
    };

    Sse::new(stream).keep_alive(
        axum::response::sse::KeepAlive::new()
            .interval(Duration::from_secs(15))
            .text("ping"),
    )
}

