import { Pill } from "@/components/shell/Primitives";
import { GenerativeBlock, parseGenerativeBlocks } from "@/components/chat/GenerativeBlock";
import { JsonRenderer } from "@/components/json/JsonRenderer";
import { cn } from "@/lib/utils";

export interface LocalMessage {
  id: string;
  role: "user" | "assistant" | "system" | "tool";
  content: string;
  timestamp: number;
  toolCalls?: Array<{ id: string; name: string; arguments: Record<string, unknown>; result?: unknown; status: string }>;
}

interface MessageBubbleProps {
  message: LocalMessage;
  onInspect: (data: unknown) => void;
  onAction?: (action: string, payload: unknown) => void;
}

export function MessageBubble({ message, onInspect, onAction }: MessageBubbleProps) {
  const isUser = message.role === "user";
  const isSystem = message.role === "system";
  const time = new Date(message.timestamp).toLocaleTimeString();

  if (isSystem) {
    return (
      <div className="flex justify-center">
        <span className="text-xs text-muted-foreground bg-muted/30 px-3 py-1 rounded-full">{message.content}</span>
      </div>
    );
  }

  // Parse generative UI blocks from assistant messages
  const segments = !isUser ? parseGenerativeBlocks(message.content) : null;
  const jsonPayload = !isUser ? parseJsonPayload(message.content) : null;

  return (
    <div className={cn("flex gap-3", isUser && "flex-row-reverse")}>
      <div className={cn(
        "h-8 w-8 rounded-full flex items-center justify-center text-xs font-bold shrink-0",
        isUser ? "bg-muted text-foreground" : "bg-primary/20 text-primary",
      )}>
        {isUser ? "OP" : "AI"}
      </div>
      <div className={cn("max-w-[75%] space-y-2", isUser && "text-right")}>
        <div className={cn(
          "rounded-lg px-4 py-2.5 text-sm",
          isUser ? "bg-primary/10 border border-primary/20 text-foreground" : "bg-card border border-border text-foreground",
        )}>
          {jsonPayload ? (
            <div
              role="button"
              tabIndex={0}
              onClick={() => onInspect(jsonPayload)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  onInspect(jsonPayload);
                }
              }}
              className="block w-full cursor-pointer text-left"
            >
              <JsonRenderer data={jsonPayload} />
            </div>
          ) : isUser || !segments ? (
            <div className="whitespace-pre-wrap">{message.content}</div>
          ) : (
            <div className="space-y-3">
              {segments.map((seg, i) =>
                seg.type === "text" ? (
                  <div key={i} className="whitespace-pre-wrap">{seg.text}</div>
                ) : (
                  <GenerativeBlock key={i} spec={seg.spec} onAction={onAction} />
                )
              )}
            </div>
          )}
        </div>
        {message.toolCalls?.map((tc) => (
          <button
            key={tc.id}
            onClick={() => onInspect(tc)}
            className="w-full text-left rounded-lg border border-border bg-muted/20 px-3 py-2 hover:border-primary/30 transition-colors"
          >
            <div className="flex items-center gap-2">
              <Pill variant={tc.status === "completed" ? "ok" : tc.status === "error" ? "danger" : "default"}>
                {tc.status}
              </Pill>
              <span className="font-mono text-xs text-foreground">{tc.name}</span>
            </div>
            {tc.result && (
              <pre className="mt-1.5 font-mono text-[11px] text-muted-foreground truncate">{JSON.stringify(tc.result).slice(0, 100)}</pre>
            )}
          </button>
        ))}
        <div className="text-[10px] text-muted-foreground">{time}</div>
      </div>
    </div>
  );
}

function parseJsonPayload(content: string): unknown | null {
  const trimmed = content.trim();
  if (!trimmed || !["{", "["].includes(trimmed[0])) return null;

  try {
    return JSON.parse(trimmed);
  } catch {
    return null;
  }
}

//! Zeroclaw route helpers backed by the D-Bus projection cache.

use anyhow::{bail, Result};
use simd_json::prelude::*;

use crate::projection_client::ProjectionCache;

#[derive(Debug, Clone)]
pub struct ZeroclawRoute {
    pub provider: String,
    pub upstream_provider: String,
    pub transport: Option<String>,
    pub model: String,
    pub hint: Option<String>,
    pub kind: Option<String>,
    pub status: String,
    pub available: bool,
    pub status_reason: Option<String>,
    pub source: Option<String>,
}

impl ZeroclawRoute {
    fn from_value(value: &simd_json::OwnedValue) -> Option<Self> {
        let model = value.get("model")?.as_str()?.to_string();
        let provider = value
            .get("provider")
            .and_then(|v| v.as_str())
            .unwrap_or("zeroclaw")
            .to_string();
        let upstream_provider = value
            .get("upstream_provider")
            .and_then(|v| v.as_str())
            .unwrap_or(&provider)
            .to_string();
        let status = value
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("declared")
            .to_string();
        let available = value
            .get("available")
            .and_then(|v| v.as_bool())
            .unwrap_or_else(|| status == "available");

        Some(Self {
            provider,
            upstream_provider,
            transport: value
                .get("transport")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            model,
            hint: value
                .get("hint")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            kind: value
                .get("kind")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            status,
            available,
            status_reason: value
                .get("status_reason")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            source: value
                .get("source")
                .and_then(|v| v.as_str())
                .map(str::to_string),
        })
    }
}

pub async fn routes(cache: &ProjectionCache) -> Option<Vec<ZeroclawRoute>> {
    let zeroclaw = crate::projection_client::get_projection(cache, "zeroclaw").await?;
    let route_values = zeroclaw.get("model_routes")?.as_array()?;
    Some(
        route_values
            .iter()
            .filter_map(ZeroclawRoute::from_value)
            .collect(),
    )
}

pub async fn route_for_model(cache: &ProjectionCache, model: &str) -> Option<ZeroclawRoute> {
    routes(cache)
        .await?
        .into_iter()
        .find(|route| route.model == model)
}

pub async fn ensure_model_available(cache: &ProjectionCache, model: &str) -> Result<()> {
    if let Some(route) = route_for_model(cache, model).await {
        if !route.available {
            let reason = route
                .status_reason
                .unwrap_or_else(|| "route is not available".to_string());
            bail!(
                "Zeroclaw route '{}' is {} but not available: {}",
                model,
                route.status,
                reason
            );
        }
    }

    Ok(())
}

