        .route(
            "/mcp/cognitive/memory/:key",
            delete(handlers::mcp::delete_memory_handler),
        )
        .route(
            "/mcp/cognitive/memory/stats",
            get(handlers::mcp::memory_stats_handler),
        )
        // MCP discovery endpoints
        .route("/mcp/_config", get(mcp::config_handler))
        // SSE events
        .route("/events", get(sse::sse_handler))
        // Privacy router endpoints
        .route("/privacy/signup", post(handlers::privacy::signup))
        .route("/privacy/verify", get(handlers::privacy::verify))
        .route(
            "/privacy/config/:user_id",
            get(handlers::privacy::get_config),
        )
        .route("/privacy/status", get(handlers::privacy::status))
        .route(
            "/privacy/credentials",
            post(handlers::privacy::set_credentials),
        )
        // Google OAuth endpoints
        .route("/privacy/google/auth", get(handlers::privacy::google_auth))
        .route(
            "/privacy/google/callback",
            get(handlers::privacy::google_callback),
        );

    // MCP JSON-RPC endpoints (profile-based and legacy)
    let mcp_route = mcp::create_mcp_router();

    // Critical Agents MCP endpoint (SSE-based, direct tool access)
    // These are added separately to avoid state conflicts
    let agents_mcp_route = Router::new()
        .route(
            "/mcp/agents",
            get(mcp_agents::mcp_agents_sse_handler_stateless),
        )
        .route(
            "/mcp/agents/message",
            post(mcp_agents::mcp_agents_message_handler_stateless),
        );

    // WebSocket route
    let ws_route = Router::new().route("/ws", get(websocket::websocket_handler));

    // Main router - agents_mcp_route FIRST so it takes precedence
    let mut router = Router::new()
        .nest("/api", api_routes)
        // Human-facing privacy verification flow (magic-link target)
        .route("/privacy/verify", get(handlers::privacy::verify_redirect))
        .route(
            "/privacy/access",
            get(handlers::privacy::privacy_access_message),
        )
        // JSON-RPC compatibility aliases (mirror /mcp)
        .route("/jsonrpc", post(mcp::jsonrpc_handler))
        .route("/rpc", post(mcp::jsonrpc_handler))
        .merge(agents_mcp_route) // Agents first (more specific)
        .nest("/mcp", mcp_route) // Nest MCP routes under /mcp (not root)
        .merge(ws_route)
        // Well-known discovery endpoint for auto-configuration
        .route(
            "/.well-known/mcp.json",
            get(mcp_discovery::mcp_discovery_handler),
        )
        .nest("/groups-admin", groups_admin::create_groups_admin_router())
        .nest("/admin", admin::admin_routes());

    // Use filesystem static files if available, otherwise fallback to embedded UI
    let static_dir =
        std::env::var("OP_WEB_STATIC_DIR").unwrap_or_else(|_| "lovable/dist".to_string());
    let static_index = std::path::Path::new(&static_dir).join("index.html");
    if static_index.exists() {
        router = router
            .fallback_service(ServeDir::new(static_dir).fallback(ServeFile::new(static_index)));
    } else if std::path::Path::new(&static_dir).exists() {
        router = router.fallback_service(
            ServeDir::new(static_dir).fallback(get(crate::embedded_ui::serve_embedded_ui)),
        );
    } else {
        router = router.fallback(crate::embedded_ui::serve_embedded_ui);
    }

    router
        .layer(Extension(state))
        .layer(axum::middleware::from_fn(security::ip_security_middleware))
        .layer(cors)
        .layer(CompressionLayer::new())
        .layer(TraceLayer::new_for_http())
}

import { create } from "zustand";
import type { HealthSnapshot, LogEntry, Agent, EventLogEntry, SseEventType } from "@/types/api";

interface EventStore {
  connected: boolean;
  health: HealthSnapshot | null;
  logs: LogEntry[];
  agents: Agent[];
  events: EventLogEntry[];
  lastError: string | null;
  eventCounts: Record<string, number>;
  latestState: Record<string, unknown>;
  latestStats: Record<string, unknown> | null;

  setConnected: (v: boolean) => void;
  setHealth: (h: HealthSnapshot) => void;
  addLog: (entry: LogEntry) => void;
  setLogs: (logs: LogEntry[]) => void;
  setAgents: (agents: Agent[]) => void;
  addEvent: (event: EventLogEntry) => void;
  setError: (err: string | null) => void;
  clearLogs: () => void;
  updateState: (key: string, value: unknown) => void;
  setStats: (stats: Record<string, unknown>) => void;
  incrementEventCount: (type: SseEventType) => void;
}

const MAX_LOGS = 1000;
const MAX_EVENTS = 500;

export const useEventStore = create<EventStore>((set) => ({
  connected: false,
  health: null,
  logs: [],
  agents: [],
  events: [],
  lastError: null,
  eventCounts: {},
  latestState: {},
  latestStats: null,

  setConnected: (connected) => set({ connected }),
  setHealth: (health) => set({ health }),
  addLog: (entry) => set((s) => ({ logs: [...s.logs, entry].slice(-MAX_LOGS) })),
  setLogs: (logs) => set({ logs }),
  setAgents: (agents) => set({ agents }),
  addEvent: (event) => set((s) => ({ events: [...s.events, event].slice(-MAX_EVENTS) })),
  setError: (lastError) => set({ lastError }),
  clearLogs: () => set({ logs: [] }),
  updateState: (key, value) => set((s) => ({
    latestState: { ...s.latestState, [key]: value },
  })),
  setStats: (stats) => set({ latestStats: stats }),
  incrementEventCount: (type) => set((s) => ({
    eventCounts: { ...s.eventCounts, [type]: (s.eventCounts[type] || 0) + 1 },
  })),
}));

import { useEffect, useRef } from "react";
import { stateSync, eventChainService, ovsdbMirror, runtimeMirror, componentRegistry } from "@/grpc/client";
import { useEventStore } from "@/stores/event-store";
import type { StateChange, ChainEvent, OvsdbUpdate, RuntimeMetricUpdate } from "@/grpc/types/operation";
import type { RegistryEvent } from "@/grpc/types/registry";
import { structToObject, valueToJs } from "@/grpc/google/protobuf/struct";

/**
 * Subscribes to all live gRPC-Web server-streams from the operation gateway:
 *   1. StateSync.Subscribe   — D-Bus property changes → latestState
 *   2. EventChain.SubscribeEvents — Audit ledger → events[]
 *   3. OvsdbMirror.Monitor   — OVS bridge/port/interface changes → latestState
 *   4. RuntimeMirror.StreamMetrics — CPU/memory/network metrics → latestStats
 *
 * All streams auto-reconnect on failure with exponential backoff.
 */
export function useEventStream() {
  const abortsRef = useRef<(() => void)[]>([]);
  const retryRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    let mounted = true;

    function connectAll() {
      if (!mounted) return;
      const aborts: (() => void)[] = [];

      const s = useEventStore.getState();
      s.setConnected(false);
      s.setError(null);

      // ── 1. StateSync — live D-Bus property updates ────────────────────
      try {
        const { stream: stateStream, abort: abortState } = stateSync.subscribe({
          includeInitialState: true,
        });
        aborts.push(abortState);

        const stateReader = stateStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await stateReader.read();
              if (done) break;
              const change = value as StateChange;
              const store = useEventStore.getState();

              // Project change into latestState
              const key = change.pluginId
                ? `${change.pluginId}.${change.memberName}`
                : change.memberName;
              store.updateState(key, valueToJs(change.newValue));

              // Track as event
              store.addEvent({
                id: change.changeId || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
                event: "state_update",
                ts: Date.now(),
                payload: change,
              });
              store.incrementEventCount("state_update");

              // Mark connected on first message
              store.setConnected(true);
              store.setError(null);
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`StateSync stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed — will retry
      }

      // ── 2. EventChain — audit ledger stream ──────────────────────────
      try {
        const { stream: chainStream, abort: abortChain } = eventChainService.subscribeEvents({
          fromEventId: 0,
        });
        aborts.push(abortChain);

        const chainReader = chainStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await chainReader.read();
              if (done) break;
              const evt = value as ChainEvent;
              const store = useEventStore.getState();

              store.addEvent({
                id: evt.eventHash || `chain-${evt.eventId}`,
                event: "audit_event",
                ts: Date.now(),
                payload: evt,
              });
              store.incrementEventCount("audit_event");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`EventChain stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      // ── 3. OvsdbMirror.Monitor — OVS changes ─────────────────────────
      try {
        const { stream: ovsStream, abort: abortOvs } = ovsdbMirror.monitor({
          database: "Open_vSwitch",
          monitorRequestsJson: JSON.stringify({
            Bridge: {},
            Port: {},
            Interface: {},
          }),
        });
        aborts.push(abortOvs);

        const ovsReader = ovsStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await ovsReader.read();
              if (done) break;
              const update = value as OvsdbUpdate;
              const store = useEventStore.getState();

              // Project into latestState under ovsdb namespace
              const key = `ovsdb.${update.table}.${update.uuid}`;
              store.updateState(
                key,
                update.newRow ? structToObject(update.newRow) : null,
              );

              store.addEvent({
                id: `ovs-${update.uuid}-${Date.now()}`,
                event: "state_update",
                ts: Date.now(),
                payload: update,
              });
              store.incrementEventCount("state_update");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`OvsdbMirror stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      // ── 4. RuntimeMirror.StreamMetrics — system metrics ───────────────
      try {
        const { stream: metricsStream, abort: abortMetrics } = runtimeMirror.streamMetrics({
          intervalSeconds: 5,
          categories: [],
        });
        aborts.push(abortMetrics);

        const metricsReader = metricsStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await metricsReader.read();
              if (done) break;
              const metric = value as RuntimeMetricUpdate;
              const store = useEventStore.getState();

              // Accumulate metrics into latestStats
              const current = store.latestStats ?? {};
              const labelKey = Object.values(metric.labels || {}).join(".");
              const metricKey = labelKey
                ? `${metric.category}.${metric.name}.${labelKey}`
                : `${metric.category}.${metric.name}`;

              store.setStats({
                ...current,
                [metricKey]: {
                  value: metric.value,
                  unit: metric.unit,
                  labels: metric.labels,
                  timestamp: metric.timestamp,
                },
              });

              store.incrementEventCount("system_stats");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`RuntimeMirror metrics error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      // ── 5. ComponentRegistry.Watch — live agent/component discovery ───
      try {
        const { stream: regStream, abort: abortReg } = componentRegistry.watch({
          componentTypes: [],
          includeExisting: true,
        });
        aborts.push(abortReg);

        const regReader = regStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await regReader.read();
              if (done) break;
              const evt = value as RegistryEvent;
              const store = useEventStore.getState();
              const comp = evt.component;

              if (comp) {
                // Maintain a running list of agents under latestState["agents"]
                const existing = (store.latestState["agents"] as Array<Record<string, unknown>>) ?? [];
                const idx = existing.findIndex((a) => a.id === comp.componentId);
                const entry: Record<string, unknown> = {
                  id: comp.componentId,
                  name: comp.name,
                  description: comp.description,
                  status: comp.status === 1 ? "running" : comp.status === 2 ? "offline" : comp.status === 3 ? "offline" : "busy",
                  capabilities: comp.capabilities ?? [],
                  activeSessions: 0,
                  memoryEntries: 0,
                  configSchema: comp.schemaJson ? (() => { try { return JSON.parse(comp.schemaJson); } catch { return {}; } })() : {},
                  configData: comp.metadata ?? {},
                  componentType: comp.componentType,
                  endpoint: comp.endpoint,
                  version: comp.version,
                  lastHeartbeat: comp.lastHeartbeat,
                };

                // Deregistered → remove; otherwise upsert
                if (evt.eventType === 2 /* DEREGISTERED */) {
                  store.updateState("agents", existing.filter((a) => a.id !== comp.componentId));
                } else if (idx >= 0) {
                  const updated = [...existing];
                  updated[idx] = entry;
                  store.updateState("agents", updated);
                } else {
                  store.updateState("agents", [...existing, entry]);
                }
              }

              store.addEvent({
                id: `reg-${evt.component?.componentId}-${Date.now()}`,
                event: "registry_event",
                ts: Date.now(),
                payload: evt,
              });
              store.incrementEventCount("registry_event");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`ComponentRegistry stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      abortsRef.current = aborts;

      // If no streams connected, schedule retry
      if (aborts.length === 0) {
        scheduleRetry();
      }
    }

    function scheduleRetry() {
      if (!mounted) return;
      const store = useEventStore.getState();
      store.setConnected(false);
      store.setError("All gRPC streams disconnected, retrying…");
      retryRef.current = setTimeout(() => {
        cleanup();
        connectAll();
      }, 5000);
    }

    function cleanup() {
      for (const abort of abortsRef.current) {
        try { abort(); } catch { /* ignore */ }
      }
      abortsRef.current = [];
      if (retryRef.current) {
        clearTimeout(retryRef.current);
        retryRef.current = null;
      }
    }

    connectAll();

    return () => {
      mounted = false;
      cleanup();
    };
  }, []);
}

/**
 * GenerativeBlock — intercepts JSON UI specification blocks inside chat messages
 * and renders them as interactive Shadcn components via SchemaRenderer.
 *
 * Detects ```json:ui ... ``` code blocks or { "$schema": "ui", ... } JSON structures.
 */
import { useState, useCallback, useMemo } from "react";
import { SchemaRenderer } from "@/components/json/SchemaRenderer";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Play } from "lucide-react";
import type { JsonSchema } from "@/types/api";

interface GenerativeBlockProps {
  spec: GenerativeSpec;
  onAction?: (action: string, payload: unknown) => void;
}

export interface GenerativeSpec {
  schema: JsonSchema;
  data?: Record<string, unknown>;
  title?: string;
  actions?: Array<{ label: string; action: string; variant?: "default" | "destructive" | "outline" }>;
}

/**
 * Parse chat message content for generative UI blocks.
 * Returns an array of segments: plain text or GenerativeSpec objects.
 */
export function parseGenerativeBlocks(content: string): Array<{ type: "text"; text: string } | { type: "ui"; spec: GenerativeSpec }> {
  const segments: Array<{ type: "text"; text: string } | { type: "ui"; spec: GenerativeSpec }> = [];

  // Match ```json:ui ... ``` blocks
  const uiBlockRegex = /```json:ui\s*\n([\s\S]*?)```/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = uiBlockRegex.exec(content)) !== null) {
    if (match.index > lastIndex) {
      segments.push({ type: "text", text: content.slice(lastIndex, match.index) });
    }
    try {
      const parsed = JSON.parse(match[1]);
      if (parsed.schema) {
        segments.push({ type: "ui", spec: parsed as GenerativeSpec });
      } else {
        segments.push({ type: "text", text: match[0] });
      }
    } catch {
      segments.push({ type: "text", text: match[0] });
    }
    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < content.length) {
    const remaining = content.slice(lastIndex);
    // Also check for inline JSON UI specs
    try {
      const parsed = JSON.parse(remaining);
      if (parsed && typeof parsed === "object" && parsed["$schema"] === "ui" && parsed.schema) {
        segments.push({ type: "ui", spec: { schema: parsed.schema, data: parsed.data, title: parsed.title, actions: parsed.actions } });
        return segments;
      }
    } catch {
      // Not JSON, treat as text
    }
    if (remaining.trim()) {
      segments.push({ type: "text", text: remaining });
    }
  }

  return segments.length > 0 ? segments : [{ type: "text", text: content }];
}

export function GenerativeBlock({ spec, onAction }: GenerativeBlockProps) {
  const [formData, setFormData] = useState<unknown>(spec.data ?? {});

  const handleAction = useCallback((action: string) => {
    onAction?.(action, formData);
  }, [formData, onAction]);

  return (
    <div className="rounded-lg border border-primary/20 bg-card/80 overflow-hidden">
      {spec.title && (
        <div className="px-3 py-2 border-b border-border/50 flex items-center gap-2">
          <Badge variant="outline" className="text-[10px] border-primary/30 text-primary">UI</Badge>
          <span className="text-xs font-medium text-foreground">{spec.title}</span>
        </div>
      )}
      <div className="p-3">
        <SchemaRenderer
          schema={spec.schema}
          data={formData}
          onChange={setFormData}
        />
      </div>
      {spec.actions && spec.actions.length > 0 && (
        <div className="px-3 py-2 border-t border-border/50 flex items-center gap-2">
          {spec.actions.map((act) => (
            <Button
              key={act.action}
              size="sm"
              variant={act.variant === "destructive" ? "destructive" : act.variant === "outline" ? "outline" : "default"}
              className="h-7 text-xs gap-1.5"
              onClick={() => handleAction(act.action)}
            >
              <Play className="h-3 w-3" />
              {act.label}
            </Button>
          ))}
        </div>
      )}
    </div>
  );
}

