        }
    }
}

//! WireGuard identity detection and peer management.

use std::process::Command;
use tracing::{debug, warn};

/// WireGuard identity provider
#[derive(Debug, Clone)]
pub struct WireGuardIdentity {
    /// Interface name (default: wg0)
    interface: String,
}

impl WireGuardIdentity {
    pub fn new() -> Self {
        let iface = std::env::var("WG_INTERFACE").unwrap_or_else(|_| "netmaker".to_string());
        Self::with_interface(&iface)
    }

    pub fn with_interface(interface: &str) -> Self {
        Self {
            interface: interface.to_string(),
        }
    }

    /// Get the local WireGuard public key (this machine's identity)
    pub fn get_local_pubkey(&self) -> anyhow::Result<String> {
        // Try environment variable first
        if let Ok(pubkey) = std::env::var("WG_PUBKEY") {
            debug!("Using WG_PUBKEY from environment");
            return Ok(pubkey);
        }

        anyhow::bail!("WG_PUBKEY not set in environment. Identity decoupling requires explicit pre-assignment.");
    }

    /// Get peer's pubkey from their IP address
    pub fn get_pubkey_for_ip(&self, peer_ip: &str) -> anyhow::Result<Option<String>> {
        let output = Command::new("wg")
            .args(["show", &self.interface, "allowed-ips"])
            .output()?;

        if !output.status.success() {
            return Ok(None);
        }

        let stdout = String::from_utf8_lossy(&output.stdout);

        // Format: pubkey\tallowed_ip1, allowed_ip2
        for line in stdout.lines() {
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() >= 2 {
                let pubkey = parts[0];
                let ips = parts[1];

                if ips.contains(peer_ip) {
                    return Ok(Some(pubkey.to_string()));
                }
            }
        }

        Ok(None)
    }

    /// Get all connected peers with their latest handshake times
    pub fn get_connected_peers(&self) -> anyhow::Result<Vec<PeerInfo>> {
        let output = Command::new("wg")
            .args(["show", &self.interface, "latest-handshakes"])
            .output()?;

        if !output.status.success() {
            return Ok(Vec::new());
        }

        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut peers = Vec::new();

        // Format: pubkey\ttimestamp
        for line in stdout.lines() {
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() >= 2 {
                let pubkey = parts[0].to_string();
                let timestamp: u64 = parts[1].parse().unwrap_or(0);

                // Only include peers with recent handshakes (within 3 minutes)
                let now = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_secs())
                    .unwrap_or(0);

                if timestamp > 0 && now - timestamp < 180 {
                    peers.push(PeerInfo {
                        pubkey,
                        last_handshake: timestamp,
                        allowed_ips: self.get_allowed_ips_for_peer(parts[0]).unwrap_or_default(),
                    });
                }
            }
        }

        Ok(peers)
    }

    /// Get the primary IPv4 address of the WireGuard interface.
    ///
    /// Uses `ip -4 addr show <iface>` and parses the first `inet` address.
    /// Returns `None` if the interface has no IPv4 address or the command fails.
    pub fn get_local_ip(&self) -> Option<String> {
        let output = Command::new("ip")
            .args(["-4", "addr", "show", &self.interface])
            .output()
            .ok()?;

        if !output.status.success() {
            return None;
        }

        let stdout = String::from_utf8_lossy(&output.stdout);
        for line in stdout.lines() {
            let trimmed = line.trim();
            if let Some(rest) = trimmed.strip_prefix("inet ") {
                // rest is e.g. "100.90.37.254/32 scope global netmaker"
                let ip = rest.split('/').next()?.trim();
                if !ip.is_empty() {
                    return Some(ip.to_string());
                }
            }
        }
        None
    }

    /// Get allowed IPs for a specific peer
    fn get_allowed_ips_for_peer(&self, pubkey: &str) -> anyhow::Result<Vec<String>> {
        let output = Command::new("wg")
            .args(["show", &self.interface, "allowed-ips"])
            .output()?;

        if !output.status.success() {
            return Ok(Vec::new());
        }

        let stdout = String::from_utf8_lossy(&output.stdout);

        for line in stdout.lines() {
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() >= 2 && parts[0] == pubkey {
                return Ok(parts[1].split(',').map(|s| s.trim().to_string()).collect());
            }
        }

        Ok(Vec::new())
    }
}

impl Default for WireGuardIdentity {
    fn default() -> Self {
        Self::new()
    }
}

/// Information about a WireGuard peer
#[derive(Debug, Clone)]
pub struct PeerInfo {
    pub pubkey: String,
    pub last_handshake: u64,
    pub allowed_ips: Vec<String>,
}

//! Zeroclaw / Antigravity proxy handlers
//!
//! Proxies chat requests to the antigravity Python SDK bot running on
//! 127.0.0.1:8081, and serves the combined schema (OpenAPI + zeroclaw
//! projection) for schema-driven UI rendering.

use axum::{
    body::Body,
    extract::Extension,
    http::StatusCode,
    response::Response,
    Json,
};
use serde::Deserialize;
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::sync::Arc;
use tracing::{error, info};

use crate::state::AppState;

/// Antigravity bridge base URL - defaults to standard Antigravity IDE bridge port
/// Can be overridden with ANTIGRAVITY_BRIDGE_URL env var
fn antigravity_base() -> String {
    std::env::var("ANTIGRAVITY_BRIDGE_URL")
        .unwrap_or_else(|_| "http://127.0.0.1:3333".to_string())
}

/// Schema-driven chat request — shape matches the antigravity bot's
/// `ChatRequest` so we can forward verbatim.
#[derive(Debug, Deserialize)]
pub struct ZeroclawChatRequest {
    pub message: String,
    #[serde(default)]
    pub session_id: Option<String>,
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
}

/// Proxy chat request to the antigravity bot.
/// POST /api/zeroclaw/chat
pub async fn zeroclaw_chat_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(120))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat", antigravity_base());

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat to antigravity bot: {} chars",
        req.message.len()
    );

    match client
        .post(&url)
        .header("Content-Type", "application/json")
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity response body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity response",
                    );
                }
            };

            let axum_status = StatusCode::from_u16(status.as_u16())
                .unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "application/json")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build response"))
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Proxy streaming chat request to the antigravity bot SSE endpoint.
/// POST /api/zeroclaw/chat/stream
pub async fn zeroclaw_chat_stream_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(300))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat/stream", antigravity_base());

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat stream to antigravity bot: {} chars",
        req.message.len()
    );

    match client
        .post(&url)
        .header("Content-Type", "application/json")
        .header("Accept", "text/event-stream")
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity stream body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity stream",
                    );
                }
            };

            let axum_status = StatusCode::from_u16(status.as_u16())
                .unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "text/event-stream")
                .header("Cache-Control", "no-cache")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build stream response"))
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Helper to build a JSON error response.
fn json_error_response(status: StatusCode, message: &str) -> Response {
    let body = simd_json::to_string(&json!({"error": message})).unwrap_or_default();
    Response::builder()
        .status(status)
        .header("Content-Type", "application/json")
        .body(Body::from(body))
        .unwrap_or_else(|_| {
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::empty())
                .unwrap()
        })
}

/// Serve the combined schema for schema-driven UI rendering.
///
/// Merges the antigravity bot's OpenAPI schema with the zeroclaw plugin
/// projection (providers, model_routes, tools, structured_output) so the
/// frontend can render the entire chat interface from a single schema.
/// GET /api/zeroclaw/schema
pub async fn zeroclaw_schema_handler(
    Extension(state): Extension<Arc<AppState>>,
) -> Response {
    // Fetch antigravity OpenAPI schema
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let openapi = match client
        .get(format!("{}/openapi.json", antigravity_base()))
        .send()
        .await
    {
        Ok(resp) => match resp.json::<Value>().await {
            Ok(v) => v,
            Err(e) => {
                error!("Failed to parse antigravity OpenAPI: {}", e);
                json!({})
            }
        },
        Err(e) => {
            error!("Failed to fetch antigravity OpenAPI: {}", e);
            json!({})
        }
    };

    // Fetch zeroclaw projection
    let zeroclaw = match crate::projection_client::get_projection(
        &state.projection_cache,
        "zeroclaw",
    )
    .await
    {
        Some(v) => v,
        None => {
            error!("Zeroclaw projection not available");
            return json_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "Zeroclaw projection not available",
            );
        }
    };

    // Build a JSON Schema for the chat form from zeroclaw providers + model_routes
    let providers = zeroclaw
        .get("providers")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|p| p.get("id").and_then(|v| v.as_str()).map(String::from))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let model_routes = zeroclaw
        .get("model_routes")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|r| {
                    let model = r.get("model").and_then(|v| v.as_str())?;
                    let hint = r.get("hint").and_then(|v| v.as_str());
                    let label = hint.map(|h| format!("{} ({h})", model)).unwrap_or_else(|| model.to_string());
                    Some(json!({"const": model, "title": label}))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let chat_schema = json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "title": "Zeroclaw Chat",
        "properties": {
            "provider": {
                "type": "string",
                "enum": providers,
                "description": "LLM provider route"
            },
            "model": {
                "type": "string",
                "oneOf": model_routes,
                "description": "Model to use for this turn"
            },
            "message": {
                "type": "string",
                "description": "Chat message",
                "minLength": 1
            }
        },
        "required": ["message"]
    });

    let schema = json!({
        "openapi": openapi,
        "zeroclaw": {
            "plugin_state": zeroclaw,
            "chat_form_schema": chat_schema,
            "structured_output": zeroclaw.get("structured_output").cloned().unwrap_or(json!({})),
            "tools": zeroclaw.get("tools").cloned().unwrap_or(json!([])),
        }
    });

    let body = simd_json::to_string(&schema).unwrap_or_default();
    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/json")
        .body(Body::from(body))
        .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build schema response"))
}

