function extractProviderOptions(schema: unknown): ProviderOption[] {
  const s = schema as {
    zeroclaw?: {
      chat_form_schema?: {
        properties?: {
          provider?: { enum?: string[]; description?: string };
        };
      };
    };
  } | null;
  const ids = s?.zeroclaw?.chat_form_schema?.properties?.provider?.enum ?? [];
  return ids.map((id) => ({ id, label: id, description: id, available: true }));
}

function extractModelOptions(schema: unknown): LlmModelOption[] {
  const s = schema as {
    zeroclaw?: {
      chat_form_schema?: {
        properties?: {
          model?: { oneOf?: Array<{ const?: string; title?: string }> };
        };
      };
    };
  } | null;
  const oneOf = s?.zeroclaw?.chat_form_schema?.properties?.model?.oneOf ?? [];
  return oneOf
    .filter(
      (o): o is { const: string; title?: string } =>
        typeof o.const === "string",
    )
    .map((o) => ({
      id: o.const,
      name: o.title ?? o.const,
      available: true,
    }));
}

