// Extract providers from zeroclaw plugin_state.providers
function extractProviderOptions(schema: unknown): ProviderOption[] {
  const s = schema as {
    zeroclaw?: {
      plugin_state?: {
        providers?: Array<{
          id: string;
          kind?: string;
          route?: string;
          aliases?: string[];
        }>;
      };
    };
  } | null;

  const providers = s?.zeroclaw?.plugin_state?.providers ?? [];

  return providers.map((p) => ({
    id: p.id,
    label: `${p.id}${p.kind ? ` (${p.kind})` : ''}`,
    description: p.route ?? p.id,
    available: true,
  }));
}

// Extract all model routes from zeroclaw plugin_state.model_routes
function extractAllModelRoutes(schema: unknown): Array<{
  id: string;
  name: string;
  provider: string;
  hint?: string;
  available: boolean;
  status?: string;
  upstream_provider?: string;
}> {
  const s = schema as {
    zeroclaw?: {
      plugin_state?: {
        model_routes?: Array<{
          model: string;
          provider: string;
          upstream_provider?: string;
          hint?: string;
          status?: string;
          available?: boolean;
        }>;
      };
    };
  } | null;

  const routes = s?.zeroclaw?.plugin_state?.model_routes ?? [];

  return routes.map((r) => ({
    id: r.model,
    name: `${r.model}${r.hint ? ` (${r.hint})` : ''}`,
    provider: r.provider,
    hint: r.hint,
    available: r.available ?? false,
    status: r.status,
    upstream_provider: r.upstream_provider,
  }));
}

// Filter models by selected provider
function filterModelsByProvider(
  allRoutes: ReturnType<typeof extractAllModelRoutes>,
  providerId: string
): LlmModelOption[] {
  return allRoutes
    .filter((r) => r.provider === providerId)
    .map((r) => ({
      id: r.id,
      name: r.name,
      available: r.available,
    }));
}

