// Fetch schema once on mount — this drives the entire UI
useEffect(() => {
  let cancelled = false;
  api.zeroclaw
    .schema()
    .then((payload) => {
      if (cancelled) return;
      setSchema(payload);

      // Extract providers
      const opts = extractProviderOptions(payload);
      setProviderOptions(opts);

      // Extract all model routes
      const routes = extractAllModelRoutes(payload);
      setAllModelRoutes(routes);

      // Set default provider
      if (opts.length > 0 && provider === FALLBACK_PROVIDER) {
        setProvider(opts[0].id);
      }
    })
    .catch((err: unknown) => {
      if (cancelled) return;
      setGatewayError(err instanceof Error ? err.message : String(err));
    });
  return () => {
    cancelled = true;
  };
}, []);

// Filter models when provider or all routes change
useEffect(() => {
  if (!provider || allModelRoutes.length === 0) {
    setModels([]);
    setModel("");
    return;
  }

  const filtered = filterModelsByProvider(allModelRoutes, provider);
  setModels(filtered);

  // Reset model if current not available in this provider
  if (filtered.length > 0) {
    const currentValid = filtered.find((m) => m.id === model);
    if (!currentValid) {
      // Prefer first available model
      const firstAvailable = filtered.find((m) => m.available !== false);
      setModel(firstAvailable?.id ?? filtered[0].id);
    }
  } else {
    setModel("");
  }
}, [provider, allModelRoutes]);

