//! D-Bus Projection Client — reads live schema-validated projections from the tree.
//!
//! All projection data is published by org.opdbus.v1 under the unified
//! `/opdbus/v1/plugins/<plugin>` tree. The interface is
//! `org.opdbus.ProjectedObjectV1` with a `JsonData` property.
//!
//! This client reads ONLY verified plugin projections — explicit paths for each
//! plugin registered through the schema registry. No dynamic tree walking.

use anyhow::Result;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use tracing::{debug, info, warn};
use zbus::Connection;

/// Cached projection data keyed by entity type.
pub type ProjectionCache = Arc<RwLock<HashMap<String, Value>>>;

const DBUS_SERVICE: &str = "org.opdbus.v1";
const PROJECTED_OBJECT_IFACE: &str = "org.opdbus.ProjectedObjectV1";

/// Verified plugin projections to read. Each path is a plugin object derived
/// from a registered plugin schema (procfs, zeroclaw, etc.).
const PROJECTION_PATHS: &[(&str, &str)] = &[
    // procfs plugin children — defined in the procfs plugin schema
    ("system.memory", "/opdbus/v1/plugins/procfs/memory"),
    ("system.cpu", "/opdbus/v1/plugins/procfs/cpuinfo"),
    ("system.load", "/opdbus/v1/plugins/procfs/loadavg"),
    ("system.network", "/opdbus/v1/plugins/procfs/net_dev"),
    ("system.processes", "/opdbus/v1/plugins/procfs/stat"),
    ("system.filesystems", "/opdbus/v1/plugins/procfs/mounts"),
    // zeroclaw plugin — single object with full state
    ("zeroclaw", "/opdbus/v1/plugins/zeroclaw"),
];

/// Start a background task that polls D-Bus projections and caches them.
pub async fn start_projection_monitor(cache: ProjectionCache) {
    let conn = match Connection::system().await {
        Ok(c) => c,
        Err(e) => {
            warn!(error = %e, "Failed to connect to system D-Bus; projection monitor disabled");
            return;
        }
    };

    info!("Connected to system D-Bus; starting projection monitor for org.opdbus.v1");

    // Initial scan
    for (entity_type, path) in PROJECTION_PATHS {
        if let Err(e) = refresh_projection(&conn, cache.clone(), entity_type, path).await {
            debug!(path = %path, error = %e, "Projection not yet available");
        }
    }

    // Periodic refresh every 3 seconds
    let mut interval = tokio::time::interval(std::time::Duration::from_secs(3));
    loop {
        interval.tick().await;
        for (entity_type, path) in PROJECTION_PATHS {
            if let Err(e) = refresh_projection(&conn, cache.clone(), entity_type, path).await {
                debug!(path = %path, error = %e, "Projection refresh failed");
            }
        }
    }
}

async fn refresh_projection(
    conn: &Connection,
    cache: ProjectionCache,
    entity_type: &str,
    path: &str,
) -> Result<()> {
    let proxy = zbus::Proxy::new(conn, DBUS_SERVICE, path, PROJECTED_OBJECT_IFACE).await?;
    let data_json: String = proxy.get_property("JsonData").await?;

    let mut bytes = data_json.into_bytes();
    let value = simd_json::to_owned_value(&mut bytes)
        .map_err(|e| anyhow::anyhow!("Failed to parse projection JSON: {}", e))?;

    let mut cache_lock = cache.write().await;
    cache_lock.insert(entity_type.to_string(), value);
    drop(cache_lock);

    debug!(entity_type = %entity_type, path = %path, "Projection cached from D-Bus");
    Ok(())
}

/// Get a cached projection by entity type.
pub async fn get_projection(cache: &ProjectionCache, entity_type: &str) -> Option<Value> {
    let cache_lock = cache.read().await;
    cache_lock.get(entity_type).cloned()
}

/// Get all cached projections.
pub async fn get_all_projections(cache: &ProjectionCache) -> HashMap<String, Value> {
    let cache_lock = cache.read().await;
    cache_lock.clone()
}

//! Zeroclaw / Antigravity proxy handlers
//!
//! Proxies chat requests to the antigravity Python SDK bot running on
//! 127.0.0.1:8081, and serves the combined schema (OpenAPI + zeroclaw
//! projection) for schema-driven UI rendering.

use axum::{
    body::Body,
    extract::Extension,
    http::StatusCode,
    response::Response,
    Json,
};
use serde::Deserialize;
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::sync::Arc;
use tracing::{error, info};

use crate::state::AppState;

/// Antigravity bridge base URL - defaults to standard Antigravity IDE bridge port
/// Can be overridden with ANTIGRAVITY_BRIDGE_URL env var
fn antigravity_base() -> String {
    std::env::var("ANTIGRAVITY_BRIDGE_URL")
        .unwrap_or_else(|_| "http://127.0.0.1:3333".to_string())
}

/// Get WireGuard identity for auth headers
fn wireguard_identity_headers() -> Vec<(&'static str, String)> {
    let mut headers = Vec::new();

    // X-WireGuard-Pubkey from environment (set by wg-xray container or host)
    if let Ok(pubkey) = std::env::var("WG_PUBKEY") {
        headers.push(("X-WireGuard-Pubkey", pubkey));
    }

    // X-Ghostbridge-Trace-ID for accountability loop
    if let Ok(trace_id) = std::env::var("GHOSTBRIDGE_TRACE_ID") {
        headers.push(("X-Ghostbridge-Trace-ID", trace_id));
    }

    // Container-scoped identity for wg-xray
    if let Ok(container_id) = std::env::var("CONTAINER_ID") {
        headers.push(("X-Container-ID", container_id));
    }

    headers
}

/// Schema-driven chat request — shape matches the antigravity bot's
/// `ChatRequest` so we can forward verbatim.
#[derive(Debug, Deserialize)]
pub struct ZeroclawChatRequest {
    pub message: String,
    #[serde(default)]
    pub session_id: Option<String>,
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
}

/// Proxy chat request to the antigravity bot.
/// POST /api/zeroclaw/chat
pub async fn zeroclaw_chat_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(120))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat", antigravity_base());

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat to antigravity bot: {} chars",
        req.message.len()
    );

    let mut request_builder = client
        .post(&url)
        .header("Content-Type", "application/json");

    // Add WireGuard identity headers for auth
    for (key, value) in wireguard_identity_headers() {
        request_builder = request_builder.header(key, value);
    }

    match request_builder
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity response body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity response",
                    );
                }
            };

            let axum_status = StatusCode::from_u16(status.as_u16())
                .unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "application/json")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build response"))
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Proxy streaming chat request to the antigravity bot SSE endpoint.
/// POST /api/zeroclaw/chat/stream
pub async fn zeroclaw_chat_stream_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(req): Json<ZeroclawChatRequest>,
) -> Response {
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(300))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            error!("Failed to build HTTP client: {}", e);
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to build HTTP client",
            );
        }
    };

    let url = format!("{}/api/chat/stream", antigravity_base());

    let body = json!({
        "message": req.message,
        "session_id": req.session_id,
        "provider": req.provider,
        "model": req.model,
    });

    info!(
        "Proxying zeroclaw chat stream to antigravity bot: {} chars",
        req.message.len()
    );

    let mut request_builder = client
        .post(&url)
        .header("Content-Type", "application/json")
        .header("Accept", "text/event-stream");

    // Add WireGuard identity headers for auth
    for (key, value) in wireguard_identity_headers() {
        request_builder = request_builder.header(key, value);
    }

    match request_builder
        .body(simd_json::to_string(&body).unwrap_or_default())
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status();
            let body_bytes = match resp.bytes().await {
                Ok(b) => b,
                Err(e) => {
                    error!("Failed to read antigravity stream body: {}", e);
                    return json_error_response(
                        StatusCode::BAD_GATEWAY,
                        "Failed to read antigravity stream",
                    );
                }
            };

            let axum_status = StatusCode::from_u16(status.as_u16())
                .unwrap_or(StatusCode::BAD_GATEWAY);
            Response::builder()
                .status(axum_status)
                .header("Content-Type", "text/event-stream")
                .header("Cache-Control", "no-cache")
                .body(Body::from(body_bytes))
                .unwrap_or_else(|_| json_error_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to build stream response"))
        }
        Err(e) => {
            error!("Antigravity bot unreachable: {}", e);
            json_error_response(
                StatusCode::BAD_GATEWAY,
                &format!("Antigravity bot unreachable: {}", e),
            )
        }
    }
}

/// Helper to build a JSON error response.
