type ChatTab = "chat" | "system-prompt";
type LlmModelOption = { id: string; name?: string; available?: boolean };
type ProviderOption = {
  id: string;
  label: string;
  description: string;
  available?: boolean;
};

const FALLBACK_PROVIDER = "factory";

function providerList(payload: unknown): string[] {
  const value = payload as {
    providers?: unknown[];
    current?: unknown;
    provider?: unknown;
  } | null;
  return Array.from(
    new Set(
      [
        value?.current,
        value?.provider,
        ...(Array.isArray(value?.providers) ? value.providers : []),
      ]
        .filter(Boolean)
        .map(String),
    ),
  );
}

function modelList(payload: unknown): LlmModelOption[] {
  const value = payload as { models?: unknown[] } | null;
  const models = Array.isArray(value?.models) ? value.models : [];
  return models
    .map((item) => {
      const model = item as {
        id?: unknown;
        name?: unknown;
        available?: unknown;
      };
      const id = model.id ?? model.name;
      if (!id) return null;
      return {
        id: String(id),
        name: String(model.name ?? id),
        available: model.available !== false,
      };
    })
    .filter(Boolean) as LlmModelOption[];
}

function historyMessages(payload: unknown): LocalMessage[] {
  const value = payload as { messages?: unknown[] } | unknown[];
  const messages = Array.isArray(value)
    ? value
    : Array.isArray(value?.messages)
      ? value.messages
      : [];

  return messages.map((item, index) => {
    const msg = item as {
      id?: unknown;
      role?: unknown;
      content?: unknown;
      timestamp?: unknown;
    };
    return {
      id: String(msg.id ?? `history-${index}`),
      role: String(msg.role ?? "assistant") as LocalMessage["role"],
      content: String(msg.content ?? ""),
      timestamp: msg.timestamp
        ? Date.parse(String(msg.timestamp)) || Date.now()
        : Date.now(),
    };
  });
}

function assistantMessage(payload: unknown): LocalMessage {
  const value = payload as {
    id?: unknown;
    role?: unknown;
    content?: unknown;
    message?: unknown;
    error?: unknown;
  };
  const body =
    value?.content ?? value?.message ?? value?.error ?? "(no response)";
  return {
    id: String(value?.id ?? `msg-${Date.now()}-resp`),
    role: String(value?.role ?? "assistant") as LocalMessage["role"],
    content: typeof body === "string" ? body : JSON.stringify(body, null, 2),
    timestamp: Date.now(),
  };
}

// Extract providers from zeroclaw plugin_state.providers
function extractProviderOptions(schema: unknown): ProviderOption[] {
  const s = schema as {
    zeroclaw?: {
      plugin_state?: {
        providers?: Array<{
          id: string;
          kind?: string;
          route?: string;
          aliases?: string[];
        }>;
      };
    };
  } | null;

  const providers = s?.zeroclaw?.plugin_state?.providers ?? [];

  return providers.map((p) => ({
    id: p.id,
    label: `${p.id}${p.kind ? ` (${p.kind})` : ''}`,
    description: p.route ?? p.id,
    available: true,
  }));
}

// Extract all model routes from zeroclaw plugin_state.model_routes
function extractAllModelRoutes(schema: unknown): Array<{
  id: string;
  name: string;
  provider: string;
  hint?: string;
  available: boolean;
  status?: string;
  upstream_provider?: string;
}> {
  const s = schema as {
    zeroclaw?: {
      plugin_state?: {
        model_routes?: Array<{
          model: string;
          provider: string;
          upstream_provider?: string;
          hint?: string;
          status?: string;
          available?: boolean;
        }>;
      };
    };
  } | null;

  const routes = s?.zeroclaw?.plugin_state?.model_routes ?? [];

  return routes.map((r) => ({
    id: r.model,
    name: `${r.model}${r.hint ? ` (${r.hint})` : ''}`,
    provider: r.provider,
    hint: r.hint,
    available: r.available ?? false,
    status: r.status,
    upstream_provider: r.upstream_provider,
  }));
}

// Filter models by selected provider
function filterModelsByProvider(
  allRoutes: ReturnType<typeof extractAllModelRoutes>,
  providerId: string
): LlmModelOption[] {
  return allRoutes
    .filter((r) => r.provider === providerId)
    .map((r) => ({
      id: r.id,
      name: r.name,
      available: r.available,
    }));
}

