        if (cancelled) return;
        setSchema(payload);

        // Extract providers
        const opts = extractProviderOptions(payload);
        setProviderOptions(opts);

        // Extract all model routes
        const routes = extractAllModelRoutes(payload);
        setAllModelRoutes(routes);

        // Set default provider
        if (opts.length > 0 && provider === FALLBACK_PROVIDER) {
          setProvider(opts[0].id);
        }
      })
      .catch((err: unknown) => {
